queries:
SELECT SUM(rebtotal) AS total_rebate, AVG(feerate - rebrate) AS avg_net_fee_rate FROM fees WHERE rebrate > 0.0005
SELECT COUNT(*) AS num_fees, SUM(feetotal) AS total_fees, SUM(rebtotal) AS total_rebates, AVG(rebrate) AS avg_rebate_rate
FROM fees
WHERE rebrate >= 0.0005;
SELECT AVG(feerate) - AVG(rebrate) AS avg_net_fee_rate
FROM fees
WHERE rebrate > (SELECT AVG(rebrate) FROM fees);
SELECT
  AVG(CASE WHEN feerate IS NOT NULL AND rebrate IS NOT NULL THEN feerate - rebrate END) AS avg_net_fee_rate,
  SUM(rebtotal) AS total_rebate
FROM fees
WHERE rebrate > 0.0001;
SELECT AVG(feerate - rebrate) AS avg_net_fee_rate, SUM(rebtotal) AS total_rebate
FROM fees
WHERE feerate IS NOT NULL AND rebrate IS NOT NULL AND rebtotal IS NOT NULL AND rebrate > 0.0001;
SELECT * FROM fees WHERE rebrate > 0.0005;
